function main(inputs) {
  var html = String(inputs.html == null ? "" : inputs.html);
  function plain(s) {
    return String(s).replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim();
  }
  var t = html.match(/<title\b[^>]*>([\s\S]*?)<\/title\s*>/i);
  var title = t ? plain(t[1]) : "";
  var m = html.match(/<main\b[^>]*>([\s\S]*?)<\/main\s*>/i);
  var mainText = m ? plain(m[1]) : "";
  if (mainText === "") {
    mainText = "空";
  }
  return { out: title + "|" + mainText };
}
